report_script:
frappe.query_reports["Bill 01"] = {
    filters: [
        {
            fieldname: "billing_month",
            label: "Billing Month",
            fieldtype: "Select",
            options: ["", "January", "February", "March", "April", "May", "June",
                      "July", "August", "September", "October", "November", "December"]
        },
        {
            fieldname: "billing_year",
            label: "Billing Year",
            fieldtype: "Int",
            default: new Date().getFullYear()
        },
        {
            fieldname: "status",
            label: "Status",
            fieldtype: "Select",
            options: ["", "Paid", "Unpaid"]
        }
    ],

    onload: function(report) {
        frappe.msgprint({
            title: __("Welcome"),
            message: __("Use filters to view bills."),
            indicator: "green"
        });
    },

    formatter: function(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);
        if (column.fieldname === "status" && data.status === "Unpaid") {
            value = `<span style="color:red; font-weight:bold;">${value}</span>`;
        } else if (column.fieldname === "status" && data.status === "Paid") {
            value = `<span style="color:green; font-weight:bold;">${value}</span>`;
        }
        return value;
    }
};
